#!/bin/bash
# Regenerates the staged generic files of the Bitvec/Float/Ptr port.
# usage: stage.sh <path to soteria/lib/bv_values>   (kanon must be on PATH)
# - generates, from the rules with [@@@lean_module] added to bitvec/float/ptr,
#   the module roots BitvecMod/, FloatMod/, PtrMod/ (generated files only) and
#   the language's interfaces, copied to Kanon/Staged/Interface/*.lean
# - HANDPATCH=<diff> applies a patch to the generated files first (Kanon bugs).
set -euo pipefail
BV=$(cd "$1" && pwd)
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT
mkdir -p "$TMP/lean" "$TMP/rules"
cp "$BV"/rules/*.kn* "$TMP/rules/"
(cd "$BV/lean" && tar cf - --exclude=.lake .) | (cd "$TMP/lean" && tar xf -)
python3 - "$TMP/rules" <<'PY'
import sys, re
d = sys.argv[1]
for m, r in [("bitvec", "BitvecMod"), ("float", "FloatMod"), ("ptr", "PtrMod")]:
    f = f"{d}/{m}.knl"
    s = open(f).read()
    if "@@@lean_module" not in s:
        i = s.index("\nuse ") + 1
        s = s[:i] + f'[@@@lean_module "{r}"]\n\n' + s[i:]
    open(f, "w").write(s)
PY
(cd "$TMP/lean" && kanon lean-all . ../rules/lang.knl)
if [ -n "${HANDPATCH:-}" ]; then (cd "$TMP/lean" && patch -s -p1 < "$HANDPATCH"); fi
for r in BitvecMod FloatMod PtrMod; do
  # drop the generated files of the repo, then copy the new ones
  if [ -d "$BV/lean/$r" ]; then
    find "$BV/lean/$r" -name '*.lean' | while read -r f; do
      head -1 "$f" | grep -q '^-- Generated by kanon' && rm "$f" || true
    done
  fi
  (cd "$TMP/lean" && find "$r" -name '*.lean' | while read -r f; do
    if head -1 "$f" | grep -q '^-- Generated by kanon'; then
      mkdir -p "$BV/lean/$(dirname "$f")"; cp "$f" "$BV/lean/$f"; fi; done)
done
mkdir -p "$BV/lean/Kanon/Staged/Interface"
for m in Bitvec Float Ptr; do
  src="$TMP/lean/Kanon/Interface/$m.lean"
  dst="$BV/lean/Kanon/Staged/Interface/$m.lean"
  { echo "-- Staged copy of Kanon/Interface/$m.lean, as kanon generates it once $m is a"
    echo "-- [@@@lean_module] (see the generic port plan); regenerated by stage.sh."
    tail -n +2 "$src" | sed -E 's/^import Kanon\.Interface\.(Bitvec|Float|Ptr)$/import Kanon.Staged.Interface.\1/'
  } > "$dst"
done
echo staged
